import{_ as r,o as d,c as e,a2 as a}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"対応ファイルマネージャー","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/file-manager-support.md","filePath":"ja-JP/user-guide/file-manager-support.md","lastUpdated":1787206077000}'),o={name:"ja-JP/user-guide/file-manager-support.md"};function s(i,t,n,h,l,p){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="対応ファイルマネージャー" tabindex="-1">対応ファイルマネージャー <a class="header-anchor" href="#対応ファイルマネージャー" aria-label="Permalink to &quot;対応ファイルマネージャー&quot;">​</a></h1><p>Lertaro は検索するだけでなく、現在使用中のファイルマネージャーやダイアログとも連携できます。対象によって、この連携は最大で次の 3 種類の意味を持ちます:</p><ul><li><strong>インライン検索ドッキング</strong> — Lertaro の検索バーが対象ウィンドウに直接埋め込まれ (<a href="./getting-started.html#_3-つのウィンドウ">インラインウィンドウ</a>)、そこから離れることなく検索できます。</li><li><strong>クイックナビゲーション</strong> — 対象ウィンドウが<a href="./hotkeys.html#クイックナビゲーション-マウス">クイックナビゲーションのマウストリガー</a> (ダブルクリック/ミドルクリック、またはインラインウィンドウ自身のロゴ) に反応し、お気に入り・履歴・クイックアクセスフォルダーのカスケードメニューを表示します。</li><li><strong>アクティブパスの検出</strong> — Lertaro は対象ウィンドウで現在開かれているフォルダーを検出できるため、検索の対象をそのフォルダーに絞り込んだり、(パスのコピーのような) パス相対のアクションをそのフォルダーに対して解決したりできます。</li></ul><p>すべての連携が 3 つとも提供されるわけではありません — 詳細は下記の表を参照してください。</p><h2 id="クイックナビゲーションの開いているフォルダー" tabindex="-1">クイックナビゲーションの開いているフォルダー <a class="header-anchor" href="#クイックナビゲーションの開いているフォルダー" aria-label="Permalink to &quot;クイックナビゲーションの開いているフォルダー&quot;">​</a></h2><p>Folder Cascader プラグインで<strong>開いているフォルダーを表示</strong>を有効にすると (既定で有効)、クイックナビゲーションにはお気に入りと履歴の前に<strong>開いているフォルダー</strong>グループが追加されます。対応するすべてのファイルマネージャーで現在開かれている実際のファイルシステムフォルダーをまとめ、重複するパスは自動的に除外します。仮想場所および既に存在しないフォルダーは表示されないため、一覧の各項目へ確実に移動できます。</p><h2 id="標準搭載-追加インストール不要" tabindex="-1">標準搭載 (追加インストール不要) <a class="header-anchor" href="#標準搭載-追加インストール不要" aria-label="Permalink to &quot;標準搭載 (追加インストール不要)&quot;">​</a></h2><p>これらは Lertaro のコア拡張機能プラグインに標準で同梱されており、個別に有効化する必要はありません。</p><table tabindex="0"><thead><tr><th>対象</th><th>インライン検索ドッキング</th><th>クイックナビゲーション</th><th>アクティブパスの検出</th></tr></thead><tbody><tr><td>Windows エクスプローラー</td><td>対応</td><td>ダブルクリックまたはミドルクリック</td><td>対応</td></tr><tr><td>モダンな開く/保存ファイルダイアログ</td><td>対応 (これ自体がインラインウィンドウです)</td><td>ミドルクリック、またはインラインウィンドウ自身のロゴを左クリック</td><td>—</td></tr><tr><td>クラシックな開く/保存ファイルダイアログ</td><td>対応</td><td>ミドルクリック、またはインラインウィンドウ自身のロゴを左クリック</td><td>—</td></tr><tr><td>クラシックなフォルダーの参照ダイアログ</td><td>対応</td><td>ミドルクリック、またはインラインウィンドウ自身のロゴを左クリック</td><td>—</td></tr></tbody></table><p>アクティブパスの検出はダイアログ自体には適用されません — Lertaro がすでにダイアログの内部にドッキングされているため、検索の対象を絞り込むための「別のウィンドウ」が存在しないためです。</p><h2 id="任意プラグイン-設定-→-プラグイン" tabindex="-1">任意プラグイン (設定 → プラグイン) <a class="header-anchor" href="#任意プラグイン-設定-→-プラグイン" aria-label="Permalink to &quot;任意プラグイン (設定 → プラグイン)&quot;">​</a></h2><p>これらはそれぞれ個別のプラグインとして提供されます。<a href="./settings/plugins.html">設定 → プラグイン</a> からインストール/有効化し、それぞれのプラグイン独自の <strong>設定</strong> ダイアログで <strong>インライン検索を有効化</strong> と <strong>クイックナビゲーションを有効化</strong> を個別に切り替えます。どちらも既定で有効です。</p><table tabindex="0"><thead><tr><th>対象</th><th>インライン検索ドッキング</th><th>クイックナビゲーション</th><th>アクティブパスの検出</th></tr></thead><tbody><tr><td>Directory Opus</td><td>対応</td><td>ファイルリストペインでのミドルクリック</td><td>対応</td></tr><tr><td>Files</td><td>対応</td><td>ファイルリストペインでのミドルクリック</td><td>対応</td></tr><tr><td>One Commander</td><td>対応</td><td>ファイルリストペインでのミドルクリック</td><td>対応</td></tr><tr><td>Total Commander</td><td>対応</td><td>ファイルリストペインでのミドルクリック</td><td>対応</td></tr><tr><td>XYplorer</td><td>対応</td><td>ファイルリストペインでのミドルクリック</td><td>対応</td></tr></tbody></table><p>これら 5 つはいずれも実行中のプロセスを照合して対象を検出します (Directory Opus と Total Commander については、UI をスクレイピングするのではなく、<code>WM_COPYDATA</code> 経由でそれぞれの公式なリモートコントロールインターフェースと通信します)。Files と One Commander はリモートコントロール用プロトコルを公開していないため、代わりに UI オートメーションを使用します。</p><h2 id="directory-opus-のインデックス済みフォルダーサイズ" tabindex="-1">Directory Opus のインデックス済みフォルダーサイズ <a class="header-anchor" href="#directory-opus-のインデックス済みフォルダーサイズ" aria-label="Permalink to &quot;Directory Opus のインデックス済みフォルダーサイズ&quot;">​</a></h2><p>Directory Opus プラグインの <strong>Lertaro サイズ列を有効化</strong> オプションを有効にすると (既定で有効)、Lertaro は Directory Opus に <strong>Lertaro Size</strong> スクリプト列を追加します。この列には、Lertaro が現在メモリ上に保持しているインデックスから、インデックス済みフォルダーの再帰的なサイズを表示します。ディスクをスキャンすることはありません。ファイル行では引き続き Directory Opus 標準のサイズ列を使用し、Lertaro がインデックスしていないフォルダーではこの列は空欄になります。このオプションを無効にすると、Lertaro はスクリプトを書き込んだり更新したりしなくなります。すでにインストール済みのスクリプトは意図的に残されます。</p><p>Directory Opus の列選択画面で <strong>Lertaro Size</strong> を追加してください。フォルダーを切り替えた後や Directory Opus の再起動後にも表示し続けるには、<strong>Folder → Folder Format → Save → Save format for all folders</strong> を使用します。ローカルドライブやネットワークドライブ用など、より具体的な Folder Format はユーザー既定の形式より優先されるため、その形式にも列を追加してください。</p><p>生成されるサイズスクリプトは Directory Opus 11、12、13 以降に対応しています。古いバージョンでは非表示の互換ランナーを使用し、各クエリの直後に一時出力を削除します。</p><h2 id="アプリケーション独自のダイアログ-任意プラグイン" tabindex="-1">アプリケーション独自のダイアログ (任意プラグイン) <a class="header-anchor" href="#アプリケーション独自のダイアログ-任意プラグイン" aria-label="Permalink to &quot;アプリケーション独自のダイアログ (任意プラグイン)&quot;">​</a></h2><p>これらは、上記の標準搭載のダイアログと同様に、サードパーティ製アプリケーション内の特定の 1 つのダイアログのみを対象としており、アプリケーション全体を対象とするものではありません。<a href="./settings/plugins.html">設定 → プラグイン</a> からインストール/有効化してください。それぞれが単一のコンポーネントとして提供され、そこに固有のオン/オフスイッチがあります (切り替える項目が 1 つしかないため、専用の設定ダイアログはありません)。</p><table tabindex="0"><thead><tr><th>対象</th><th>インライン検索ドッキング</th><th>クイックナビゲーション</th><th>アクティブパスの検出</th></tr></thead><tbody><tr><td>WPS Office の「開く/保存」ダイアログ</td><td>対応</td><td>ミドルクリック、またはインラインウィンドウ自身のロゴを左クリック</td><td>—</td></tr><tr><td>WinRAR の展開ダイアログ</td><td>対応</td><td>ミドルクリック、またはインラインウィンドウ自身のロゴを左クリック</td><td>—</td></tr><tr><td>Bandizip の展開ダイアログ</td><td>対応</td><td>ミドルクリック、またはインラインウィンドウ自身のロゴを左クリック</td><td>—</td></tr><tr><td>Bandizip のファイル追加ダイアログ</td><td>対応</td><td>ミドルクリック、またはインラインウィンドウ自身のロゴを左クリック</td><td>—</td></tr><tr><td>AutoCAD の開く/保存ダイアログ</td><td>対応</td><td>ミドルクリック、またはインラインウィンドウ自身のロゴを左クリック</td><td>—</td></tr></tbody></table><p>ウィンドウタイトルではなくコントロール構造によって検出しているため、各アプリケーションが提供するどの言語パックでも動作します。WPS の項目は文書・表計算・プレゼンテーション・PDF リーダーを対象としており、これらはいずれも同一のダイアログを使用します。WPS は Windows 標準のダイアログではなく独自のものを使うため、専用のプラグインが必要になります。AutoCAD の項目は AutoCAD 固有の開く/保存ダイアログを対象とします。これらは標準の Windows 共通ダイアログクラスを使いますがコントロール構造が異なるため、専用プラグインで対応しています。ほとんどのアプリケーションが上記の標準搭載のダイアログでカバーされるのはそのためです。それらと同様、アクティブパスの検出は適用されません — Lertaro はすでにダイアログ自体の内部にドッキングされており、検索の対象を絞り込むための別のウィンドウが存在しないためです。</p><hr><p>ここに記載のないファイルマネージャー向けに独自の連携を構築したい場合は、開発者マニュアルの<a href="./../dev-guide/sdk/system-adapters.html">システム / ダイアログアダプター</a>を参照してください。</p>',24)])])}const g=r(o,[["render",s]]);export{c as __pageData,g as default};
